@spec tv_master_channel_spec  src=tests/specs/tv_master_channel_spec.lua  loc=305  cases=15
@exercises dataStore (h.ds), trackerManager (h.tm), trackerView (h.vm), editCursor (h.ec), midiManager (h.fm), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, vm:setGridSize, ec:setPos, vm:hideExtraCol, ds:get, vm:addExtraCol, vm:toggleChannelMute, vm:toggleChannelSolo, vm:isChannelMuted, vm:isChannelSoloed, vm:isChannelEffectivelyMuted, ec:col, vm:setPaletteParam, vm:automateParam, vm:paramBinding, tm:freezeEligible, tm:freezeRegion, fm:dump, vm:rebuild, ec:extendTo, clipboard:collect, ec:selClear, clipboard:pasteClip, ec:selectChannel, vm:fxHostForEdit, vm:scroll
@harness   mk, r._state.projectTracks, r._state.projectItems

# Intent
  Channel 0 is the master channel: an fx-only strip left of channel 1, always carrying at
  least one column, so a global region is always addressable. The strip is view-built; the
  regions on it run on every MIDI channel. see docs/trackerView.md § Addressing a chain

# Helpers
  @fn injectGlobals(h, list)  @ 11-20
      -- Global regions are ordinary stored regions at chan 0; each entry overrides the defaults,
      -- and the uuid is positional ('fxr-1', 'fxr-2', ...), as tv_fx_region_spec does for channels.
  @fn colsOn(h, chan)  @ 22-28

# Cases
  @case 'an empty document opens with the master fx strip as column 1'  [harness]  @ 35-50
  @case 'the strip sits left of channel 1'  [harness]  @ 54-62
  @case 'a global region renders in the master strip and on no MIDI channel'  [harness]  @ 68-83
  @case 'overlapping global regions pack into sibling columns on channel 0'  [harness]  @ 87-100
  @case 'hide refuses on the master strip'  [harness]  @ 106-119
  @case 'add-column refuses on the master strip'  [harness]  @ 123-137
  @case 'mute and solo refuse on the master strip'  [harness]  @ 141-155
  @case 'parameter automation refuses on the master strip'  [harness]  @ 159-174
  @case 'freeze refuses a global region'  [harness]  @ 178-191
  @case 'paste drops a region rebased onto the master channel'  [harness]  @ 196-222
  @case 'channel select stands, and a selection on the strip mints a global region'  [harness]  @ 228-241
  @case 'the caret opens on channel 1 lane 1, not on the strip'  [harness]  @ 247-259
  @case 'the strip stands through the first rebuild, before the pane has a width'  [harness]  @ 265-270
  @case 'a take swap brings the scroll home, so the strip stands left of the caret'  [harness]  @ 274-284
  @case 'a global region runs its chain on every MIDI channel'  [harness]  @ 292-302

